package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var t int64 = 1
	for t > 0 {
		t--
		var n, k int64
		fmt.Fscan(reader, &n, &k)
		var l int64 = -1
		var r int64 = n + 1
		for r-l > 1 {
			m := (l + r) / 2
			if (n-m)*(n-m+1)/2 - m > k {
				l = m
			} else {
				r = m
			}
		}
		fmt.Fprintln(writer, r)
	}
}
